<?php
require 'config/auth.php';require 'config/db.php';require_permission('report.view');
$year=(int)($_GET['year']??$_POST['year']??fiscal_year_for_date());
$unitId=is_admin()?(int)($_GET['unit_id']??$_POST['unit_id']??0):current_unit_id();
$q=trim($_GET['q']??'');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_permission('control.manage');
    $id=(int)($_POST['id']??0);$status=$_POST['status']??'';
    if($id<1||!in_array($status,['draft','ready'],true))$error='สถานะไม่ถูกต้อง';
    else{
        $sql='UPDATE control_accounts SET status=?,updated_at=NOW() WHERE id=? AND fiscal_year=?'.(is_admin()?'':' AND unit_id=?');
        $stmt=$conn->prepare($sql);is_admin()?$stmt->bind_param('sii',$status,$id,$year):$stmt->bind_param('siii',$status,$id,$year,$unitId);$stmt->execute();
        header('Location: report_review.php?year='.$year.'&unit_id='.$unitId.'&saved=1');exit;
    }
}
$units=is_admin()?$conn->query('SELECT id,unit_code,unit_name FROM units ORDER BY unit_code')->fetch_all(MYSQLI_ASSOC):[];
$sql="SELECT ca.id,ca.budget_code,ca.item_name,ca.gfmis_code,ca.activity_code,ca.received_amount,ca.status,ca.source_transfer_id,u.unit_code,
COALESCE(SUM(CASE WHEN e.entry_type='increase' THEN e.amount ELSE 0 END),0) extra,
COALESCE(SUM(CASE WHEN e.entry_type IN ('transfer_out','return_army','remittance') THEN e.amount ELSE 0 END),0) outgoing,
COALESCE(SUM(CASE WHEN e.entry_type='payment' THEN e.amount ELSE 0 END),0) paid
FROM control_accounts ca JOIN units u ON u.id=ca.unit_id LEFT JOIN active_control_entries e ON e.control_account_id=ca.id WHERE ca.cancelled_at IS NULL AND ca.fiscal_year=?";
$types='i';$params=[$year];if($unitId>0){$sql.=' AND ca.unit_id=?';$types.='i';$params[]=$unitId;}
if($q!==''){$sql.=' AND (ca.budget_code LIKE ? OR ca.item_name LIKE ? OR ca.gfmis_code LIKE ?)';$types.='sss';$like='%'.$q.'%';array_push($params,$like,$like,$like);}
$sql.=' GROUP BY ca.id ORDER BY ca.id DESC';$stmt=$conn->prepare($sql);$stmt->bind_param($types,...$params);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$totals=['received'=>0,'paid'=>0,'balance'=>0];foreach($rows as $r){$totals['received']+=(float)$r['received_amount']+(float)$r['extra'];$totals['paid']+=(float)$r['paid'];$totals['balance']+=(float)$r['received_amount']+(float)$r['extra']-(float)$r['outgoing']-(float)$r['paid'];}
?>
<!doctype html><html lang="th"><head><meta name="viewport" content="width=device-width, initial-scale=1"><meta charset="utf-8"><title>ตรวจสอบบัญชีคุมก่อนรายงาน</title><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"></head><body><?php require 'template/nav.php';?><main class="container">
<section class="panel"><h1 class="page-title">ตรวจสอบและแก้ไขก่อนส่งรายงาน</h1><p class="page-subtitle">ยอดเงินคำนวณจากรายการในบัญชีคุมทุกครั้ง ข้อมูลที่แก้ไขจะอัปเดตรายงาน</p><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert alert-success">บันทึกสถานะแล้ว</div><?php endif;?><form method="get" class="toolbar"><label>ปีงบประมาณ</label><input type="number" name="year" value="<?=$year?>" style="width:150px"><?php if(is_admin()):?><select name="unit_id" style="width:300px"><option value="0">ทุกหน่วย</option><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>" <?=$unitId===(int)$u['id']?'selected':''?>><?=htmlspecialchars($u['unit_code'].' '.$u['unit_name'])?></option><?php endforeach;?></select><?php endif;?><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="รหัสงบประมาณ / รายการ / GFMIS" style="max-width:300px"><button class="btn btn-primary">ค้นหา</button><a class="btn btn-success" href="report_send.php?year=<?=$year?>&unit_id=<?=$unitId?>">ส่งออกรายงาน</a></form><div class="kpi-grid"><div class="kpi-card"><p class="label">จำนวนบัญชี</p><p class="value"><?=count($rows)?></p></div><div class="kpi-card"><p class="label">รับรวม</p><p class="value"><?=number_format($totals['received'],2)?></p></div><div class="kpi-card"><p class="label">ตัดจ่าย</p><p class="value"><?=number_format($totals['paid'],2)?></p></div><div class="kpi-card"><p class="label">คงเหลือ</p><p class="value"><?=number_format($totals['balance'],2)?></p></div></div></section>
<section class="panel"><div class="table-wrap"><table><tr><th>หน่วย</th><th>รหัสงบประมาณ / รายการ</th><th>GFMIS / กิจกรรม</th><th class="text-right">รับรวม</th><th class="text-right">ตัดจ่าย</th><th class="text-right">คงเหลือ</th><th>สถานะ</th><th>ตรวจ/แก้</th></tr><?php foreach($rows as $r):$balance=(float)$r['received_amount']+(float)$r['extra']-(float)$r['outgoing']-(float)$r['paid'];?><tr><td><?=htmlspecialchars($r['unit_code'])?></td><td><strong><?=htmlspecialchars($r['budget_code'])?></strong><div><?=htmlspecialchars($r['item_name'])?></div></td><td><?=htmlspecialchars($r['gfmis_code'])?><div><?=htmlspecialchars($r['activity_code'])?></div></td><td class="text-right"><?=number_format((float)$r['received_amount']+(float)$r['extra'],2)?></td><td class="text-right"><?=number_format((float)$r['paid'],2)?></td><td class="text-right"><?=number_format($balance,2)?></td><td><?=htmlspecialchars($r['status'])?></td><td><a href="control_account_detail.php?id=<?=(int)$r['id']?>">ดูรายการเบิก</a><?php if($r['source_transfer_id']&&has_permission('budget.edit')):?> · <a href="edit_budget.php?id=<?=(int)$r['source_transfer_id']?>">แก้ข้อมูลต้นทาง</a><?php endif;?><?php if(has_permission('control.manage')):?><form method="post" class="toolbar"><?=csrf_field()?><?=request_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="unit_id" value="<?=$unitId?>"><select name="status"><option value="draft" <?=$r['status']==='draft'?'selected':''?>>ฉบับร่าง</option><option value="ready" <?=$r['status']==='ready'?'selected':''?>>พร้อมส่งออก</option></select><button class="btn btn-primary">บันทึกสถานะ</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8">ไม่พบรายการบัญชีคุม</td></tr><?php endif;?></table></div></section></main></body></html>
